import{_ as t}from"./chunks/en_editace_domeny.DnmVV4IM.js";import{_ as a,o as i,c as o,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/firstofall/en_faktury_domeny.png",f=JSON.parse('{"title":"Billing System","description":"","frontmatter":{"title":"Billing System","wiki":"en:firstofall:invoicing"},"headers":[],"relativePath":"en/firstofall/invoicing.md","filePath":"en/firstofall/invoicing.md","lastUpdated":1794388980000}'),r={name:"en/firstofall/invoicing.md"};function d(l,e,c,h,p,m){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="billing-system" tabindex="-1">Billing System <a class="header-anchor" href="#billing-system" aria-label="Permalink to &quot;Billing System&quot;">​</a></h1><p>The billing and payment process for the Buildary.online service depends on the mode in which your domain operates.</p><ul><li><strong>Trial Mode</strong> - 30 days from the creation of the domain; no fees are charged or payments required during this period</li><li><strong>Standard Mode</strong> - the rules described below apply to this mode; it is the default mode</li><li><strong>Individual Mode</strong> - the relationship and billing are governed by an individually agreed contract, and the rules described below do not apply</li></ul><h2 id="standard-domain-mode" tabindex="-1">Standard Domain Mode <a class="header-anchor" href="#standard-domain-mode" aria-label="Permalink to &quot;Standard Domain Mode&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+t+'" alt="Paid Mode Option" width="600" loading="lazy"></figure><p>In this mode, billing takes place once every 3 months in arrears, always for a specific project, at a rate based on the number of users and modules used on the project. See <a href="http://www.buildary.online/cs/cena-cz" target="_blank" rel="noreferrer">http://www.buildary.online/cs/cena-cz</a> or <a href="http://www.buildary.online/sk/cena." target="_blank" rel="noreferrer">http://www.buildary.online/sk/cena.</a></p><p>The first invoice is issued three months after the project is created or after switching to paid mode.</p><p>You switch to paid, or standard, mode through Domain Settings. Click the pencil icon at the end of the row for the relevant domain to open the Edit Domain window, where the <strong>Switch to Paid Mode</strong> button is available at the bottom. To switch to paid mode, all billing details must be completed, including the billing contact. Payment Requests and, after payment has been received and matched, Tax Documents will be sent to the specified email address or addresses.</p><p>At the end of the 30-day trial period, the application notifies you that the trial has ended and offers the option to switch to paid mode.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>It is the <strong>domain</strong> that is switched to paid mode. It is therefore important to switch the domain in which your projects are or will be created. This means that you do not need to switch your personal domain to paid mode if you do not intend to create projects there but have a separate corporate domain for this purpose. In that case, it is sufficient to switch only the corporate domain to paid mode. More information about corporate domains can be found in a separate section of the Help.</p></div><h3 id="domain-billing" tabindex="-1">Domain Billing <a class="header-anchor" href="#domain-billing" aria-label="Permalink to &quot;Domain Billing&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="Paid Mode Option" width="600" loading="lazy"></figure><p>The system automatically generates and sends a <strong>Payment Request</strong> once every three months for each project separately. You must make the payment based on this document and use the corresponding variable symbol. After the payment is received, the system automatically generates and sends an invoice, i.e. a <strong>Tax Document</strong>, as confirmation of the amount paid. This invoice is final.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>An overview of all documents issued for the domain&#39;s projects is available in the <strong>Domain Billing</strong> tab. After opening the Paid or Unpaid invoices for a particular project, all issued documents (that is, the Payment Request and, where applicable, the Tax Document) are available as attachments, <strong>where they can be downloaded at any time</strong>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The payment due date for an invoice (Payment Request) is 1 month. If payment is not received by the due date, the system will start sending reminders. If payment is still not received <strong>one month after the due date</strong>, <strong>access to the project will be suspended</strong> for all users. Access will be restored after payment is received. If payment is still not received after another month (that is, <strong>2 months after the due date</strong>), the project will be marked by the system <strong>For Deletion</strong>. The user will also be notified by email that the project is being terminated due to non-payment. If the outstanding payment is made within 3 months of the system terminating the project, the project will be restored to an active state and can be used again. If payment is not received within this period, the project will be <strong>permanently deleted</strong>. <strong>Make sure your invoices are paid on time.</strong> This will help avoid unnecessary complications for both parties.</p><p>Until the outstanding payment has been made, the system will not allow a new project to be created in the domain. If you need to create a new project but there are unpaid invoices associated with the domain, they must be paid first, even if they relate to projects that were deleted a long time ago.</p></div><h2 id="ending-billing" tabindex="-1">Ending Billing <a class="header-anchor" href="#ending-billing" aria-label="Permalink to &quot;Ending Billing&quot;">​</a></h2><p>In the standard domain mode, billing applies only to active projects. To stop billing for a project, you must also terminate the project in the application. Details on terminating a project are described in a separate section of the Help.</p>',17)])])}const b=a(r,[["render",d]]);export{f as __pageData,b as default};
